  description += 'Description of image '+n+':\n\r'+item.description+'\n\r';
  n++
}

return {
  desc: description+'\n\r'+ 'Target Prompt:\n\r'+$input.first().json.prompt
}

const result = JSON.parse($input.first().json.content.parts[0].text);
const prompt = result.final_prompt;
let related = [];
let payload = {
    "url": "https://api.kie.ai/api/v1/jobs/createTask",
    "config": {
      "model": "gpt-image-2-5-flare-text-to-image",
      "input": {
        "prompt": prompt,
        "aspect_ratio": "16:9",
        "resolution": "1K",
        "background": "auto"
       }
    } 
}
let x = 1;
for (const item of $('Prepare Image').first().json.parsed) {
  if (!result.excluded_images.includes(x)) {
    related.push(item.url);
  }
 x++;
}
if (related.length > 0) {
    payload.config.model ='gpt-image-2-5-flare-image-to-image';
  payload.config.input.input_urls = related;
}


return payload;

